'use strict';

// MODULES //

import dtypes from '@stdlib/ndarray/dtypes';
import glastIndexOfTruthy from './../../../ext/base/ndarray/glast-index-of-truthy';
import dlastIndexOfTruthy from './../../../ext/base/ndarray/dlast-index-of-truthy';
import slastIndexOfTruthy from './../../../ext/base/ndarray/slast-index-of-truthy';
import factory from '@stdlib/ndarray/base/unary-reduce-strided1d-dispatch-factory';


// VARIABLES //

var idtypes0 = dtypes( 'all' ); // input ndarray
var idtypes1 = dtypes( 'integer_index_and_generic' ); // from index ndarray
var odtypes = dtypes( 'integer_index_and_generic' );
var policies = {
	'output': 'integer_index_and_generic',
	'casting': 'none'
};
var table = {
	'types': [
		'float64',
		'float32'

		// FIXME: add specialized support for `clastIndexOfTruthy` and `zlastIndexOfTruthy` once the corresponding packages are implemented
	],
	'fcns': [
		dlastIndexOfTruthy,
		slastIndexOfTruthy
	],
	'default': glastIndexOfTruthy
};


// MAIN //

/**
* Returns the index of the last truthy element along an ndarray dimension.
*
* ## Notes
*
* -   If unable to find a truthy element along an ndarray dimension, the corresponding element in the returned ndarray is `-1`.
* -   The function explicitly treats `NaN` values as falsy.
*
* @private
* @name lastIndexOfTruthy
* @type {Function}
* @param {ndarrayLike} x - input ndarray
* @param {ndarrayLike} fromIndex - indices from which to begin searching
* @param {Options} [options] - function options
* @param {IntegerArray} [options.dims] - list of dimensions over which to perform operation
* @param {*} [options.dtype] - output ndarray data type
* @throws {TypeError} first argument must be an ndarray-like object
* @throws {TypeError} second argument must be an ndarray-like object
* @throws {TypeError} options argument must be an object
* @throws {RangeError} dimension indices must not exceed input ndarray bounds
* @throws {RangeError} number of dimension indices must not exceed the number of input ndarray dimensions
* @throws {Error} must provide valid options
* @returns {ndarray} output ndarray
*
* @example
* import Float64Array from '@stdlib/array/float64';
* import scalar2ndarray from '@stdlib/ndarray/from-scalar';
* import ndarray from '@stdlib/ndarray/ctor';
*
* // Create a data buffer:
* var xbuf = new Float64Array( [ 0.0, 0.0, 1.0, 0.0, 3.0, 0.0 ] );
*
* // Define the shape of the input array:
* var sh = [ 6 ];
*
* // Define the array strides:
* var sx = [ 1 ];
*
* // Define the index offset:
* var ox = 0;
*
* // Create an input ndarray:
* var x = new ndarray( 'float64', xbuf, sh, sx, ox, 'row-major' );
*
* // Create a from index ndarray:
* var fromIndex = scalar2ndarray( -1, {
*     'dtype': 'int32'
* });
*
* // Perform operation:
* var out = lastIndexOfTruthy( x, fromIndex );
* // returns <ndarray>[ 4 ]
*/
var lastIndexOfTruthy = factory( table, [ idtypes0, idtypes1 ], odtypes, policies );


// EXPORTS //

export default lastIndexOfTruthy;

// exports: { "assign": "lastIndexOfTruthy.assign" }
