'use strict';

// MODULES //

import numelDimension from '@stdlib/ndarray/base/numel-dimension';
import clipIndex from '@stdlib/ndarray/base/clip-index';
import getStride from '@stdlib/ndarray/base/stride';
import getOffset from '@stdlib/ndarray/base/offset';
import getData from '@stdlib/ndarray/base/data-buffer';
import ndarraylike2scalar from '@stdlib/ndarray/base/ndarraylike2scalar';
import { ndarray as strided } from './../../../../../ext/base/cfill';


// MAIN //

/**
* Fills a one-dimensional single-precision complex floating-point ndarray with a specified scalar constant.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the scalar constant.
*     -   a zero-dimensional ndarray containing the starting index (inclusive).
*     -   a zero-dimensional ndarray containing the ending index (exclusive).
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {ndarray} input ndarray
*
* @example
* import Complex64Vector from '@stdlib/ndarray/vector/complex64';
* import scalar2ndarray from '@stdlib/ndarray/from-scalar';
* import Complex64 from '@stdlib/complex/float32/ctor';
*
* var x = new Complex64Vector( [ 1.0, 2.0, -2.0, 3.0, 4.0, -6.0, 5.0, 7.0 ] );
*
* var alpha = scalar2ndarray( new Complex64( 5.0, 5.0 ), {
*     'dtype': 'complex64'
* });
*
* var start = scalar2ndarray( 0, {
*     'dtype': 'generic'
* });
*
* var end = scalar2ndarray( 2, {
*     'dtype': 'generic'
* });
*
* var out = cfill( [ x, alpha, start, end ] );
* // returns <ndarray>[ <Complex64>[ 5.0, 5.0 ], <Complex64>[ 5.0, 5.0 ], <Complex64>[ 4.0, -6.0 ], <Complex64>[ 5.0, 7.0 ] ]
*/
function cfill( arrays ) {
	var stride;
	var offset;
	var alpha;
	var start;
	var end;
	var N;
	var x;

	x = arrays[ 0 ];
	alpha = ndarraylike2scalar( arrays[ 1 ] );

	N = numelDimension( x, 0 );
	start = clipIndex( ndarraylike2scalar( arrays[ 2 ] ), N );
	end = clipIndex( ndarraylike2scalar( arrays[ 3 ] ), N );
	if ( start >= end ) {
		return x;
	}
	stride = getStride( x, 0 );
	offset = getOffset( x ) + ( stride*start );

	strided( end-start, alpha, getData( x ), stride, offset );
	return x;
}


// EXPORTS //

export default cfill;
