'use strict';

/**
* Return the index of the first element in a sorted strided array which is greater than or equal to a specified search element.
*
* @module @stdlib/blas/ext/base/gindex-of-greater-than-equal-sorted
*
* @example
* import gindexOfGreaterThanEqualSorted from '@stdlib/blas/ext/base/gindex-of-greater-than-equal-sorted';
*
* var x = [ 1.0, 2.0, 2.0, 3.0 ];
*
* var idx = gindexOfGreaterThanEqualSorted( x.length, 2.0, x, 1 );
* // returns 1
*
* @example
* import gindexOfGreaterThanEqualSorted from '@stdlib/blas/ext/base/gindex-of-greater-than-equal-sorted';
*
* var x = [ 1.0, 2.0, 2.0, 3.0 ];
*
* var idx = gindexOfGreaterThanEqualSorted.ndarray( x.length, 2.0, x, 1, 0 );
* // returns 1
*/

// MODULES //

import setReadOnly from '@stdlib/utils/define-nonenumerable-read-only-property';
import main from './main.js';
import ndarray from './ndarray.js';


// MAIN //

setReadOnly( main, 'ndarray', ndarray );


// EXPORTS //

export default main;
