'use strict';

// MODULES //

import numelDimension from '@stdlib/ndarray/base/numel-dimension';
import getStride from '@stdlib/ndarray/base/stride';
import getOffset from '@stdlib/ndarray/base/offset';
import getData from '@stdlib/ndarray/base/data-buffer';
import { ndarray as strided } from './../../../../../ext/base/cwhere';


// MAIN //

/**
* Takes elements from one of two one-dimensional single-precision complex floating-point ndarrays depending on a condition.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional condition ndarray.
*     -   first one-dimensional input ndarray.
*     -   second one-dimensional input ndarray.
*     -   a one-dimensional output ndarray.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {ndarray} output ndarray
*
* @example
* import BooleanVector from '@stdlib/ndarray/vector/bool';
* import Complex64Vector from '@stdlib/ndarray/vector/complex64';
*
* var condition = new BooleanVector( [ true, false, true ] );
* var x = new Complex64Vector( [ 1.0, -1.0, 2.0, -2.0, 3.0, -3.0 ] );
* var y = new Complex64Vector( [ 4.0, -4.0, 5.0, -5.0, 6.0, -6.0 ] );
* var out = new Complex64Vector( 3 );
*
* var v = cwhere( [ condition, x, y, out ] );
* // returns <ndarray>[ <Complex64>[ 1.0, -1.0 ], <Complex64>[ 5.0, -5.0 ], <Complex64>[ 3.0, -3.0 ] ]
*/
function cwhere( arrays ) {
	var condition;
	var out;
	var x;
	var y;

	condition = arrays[ 0 ];
	x = arrays[ 1 ];
	y = arrays[ 2 ];
	out = arrays[ 3 ];
	strided( numelDimension( condition, 0 ), getData( condition ), getStride( condition, 0 ), getOffset( condition ), getData( x ), getStride( x, 0 ), getOffset( x ), getData( y ), getStride( y, 0 ), getOffset( y ), getData( out ), getStride( out, 0 ), getOffset( out ) ); // eslint-disable-line max-len
	return out;
}


// EXPORTS //

export default cwhere;
