'use strict';

// MODULES //

import hasOwnProp from '@stdlib/assert/has-own-property';
import isPlainObject from '@stdlib/assert/is-plain-object';
import { isPrimitive as isInteger } from '@stdlib/assert/is-integer';
import isndarrayLike from '@stdlib/assert/is-ndarray-like';
import broadcastScalar from '@stdlib/ndarray/base/broadcast-scalar';
import maybeBroadcastArray from '@stdlib/ndarray/base/maybe-broadcast-array';
import nonCoreShape from '@stdlib/ndarray/base/complement-shape';
import getShape from '@stdlib/ndarray/shape';
import getOrder from '@stdlib/ndarray/order';
import format from '@stdlib/string/format';
import defaults from '@stdlib/ndarray/defaults';
import base from './base.js';


// VARIABLES //

var DEFAULT_DTYPE = defaults.get( 'dtypes.integer_index' );


// MAIN //

/**
* Returns the index of the first falsy element along an ndarray dimension.
*
* ## Notes
*
* -   If unable to find a falsy element along an ndarray dimension, the corresponding element in the returned ndarray is `-1`.
* -   The function explicitly treats `NaN` values as falsy.
*
* @param {ndarrayLike} x - input ndarray
* @param {(ndarrayLike|integer)} [fromIndex=0] - index from which to begin searching
* @param {Options} [options] - function options
* @param {integer} [options.dim=-1] - dimension over which to perform operation
* @param {boolean} [options.keepdims=false] - boolean indicating whether the reduced dimensions should be included in the returned ndarray as singleton dimensions
* @param {*} [options.dtype] - output ndarray data type
* @throws {TypeError} first argument must be an ndarray-like object
* @throws {TypeError} second argument must be either an ndarray-like object or an integer
* @throws {TypeError} options argument must be an object
* @throws {RangeError} dimension index must not exceed input ndarray bounds
* @throws {RangeError} first argument must have at least one dimension
* @throws {Error} must provide valid options
* @returns {ndarray} output ndarray
*
* @example
* import Float64Array from '@stdlib/array/float64';
* import ndarray from '@stdlib/ndarray/ctor';
*
* // Create a data buffer:
* var xbuf = new Float64Array( [ 1.0, 3.0, 0.0, 2.0, 0.0, 4.0 ] );
*
* // Define the shape of the input array:
* var sh = [ 2, 3 ];
*
* // Define the array strides:
* var sx = [ 3, 1 ];
*
* // Define the index offset:
* var ox = 0;
*
* // Create an input ndarray:
* var x = new ndarray( 'float64', xbuf, sh, sx, ox, 'row-major' );
*
* // Perform operation:
* var out = indexOfFalsy( x );
* // returns <ndarray>[ 2, 1 ]
*/
function indexOfFalsy( x, fromIndex ) {
	var hasOptions;
	var options;
	var nargs;
	var opts;
	var fidx;
	var iflg;
	var ord;
	var sh;

	nargs = arguments.length;
	if ( !isndarrayLike( x ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an ndarray. Value: `%s`.', x ) );
	}
	// Resolve input ndarray meta data:
	ord = getOrder( x );

	// Initialize an options object:
	opts = {
		'dims': [ -1 ], // default behavior is to perform a reduction over the last dimension
		'keepdims': false
	};

	// Initialize the `fromIndex` to the first element along a dimension:
	fidx = 0;

	// Initialize a flag indicating whether the `fromIndex` argument is a scalar:
	iflg = true;

	// Initialize a flag indicating whether an `options` argument was provided:
	hasOptions = false;

	// Case: indexOfFalsy( x, ??? )
	if ( nargs === 2 ) {
		// Case: indexOfFalsy( x, from_index_scalar )
		if ( isInteger( fromIndex ) ) {
			fidx = fromIndex;
		}
		// Case: indexOfFalsy( x, from_index_ndarray )
		else if ( isndarrayLike( fromIndex ) ) {
			fidx = fromIndex;
			iflg = false;
		}
		// Case: indexOfFalsy( x, options )
		else {
			options = fromIndex;
			hasOptions = true;
		}
	}
	// Case: indexOfFalsy( x, from_index, options )
	else if ( nargs > 2 ) {
		// Case: indexOfFalsy( x, from_index_scalar, options )
		if ( isInteger( fromIndex ) ) {
			fidx = fromIndex;
		}
		// Case: indexOfFalsy( x, from_index_ndarray, options )
		else if ( isndarrayLike( fromIndex ) ) {
			fidx = fromIndex;
			iflg = false;
		}
		// Case: indexOfFalsy( x, ???, options )
		else {
			throw new TypeError( format( 'invalid argument. Second argument must be either an ndarray or an integer. Value: `%s`.', fromIndex ) );
		}
		options = arguments[ 2 ];
		hasOptions = true;
	}
	if ( hasOptions ) {
		if ( !isPlainObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		// Resolve provided options...
		if ( hasOwnProp( options, 'dim' ) ) {
			opts.dims[ 0 ] = options.dim;
		}
		if ( hasOwnProp( options, 'keepdims' ) ) {
			opts.keepdims = options.keepdims;
		}
		if ( hasOwnProp( options, 'dtype' ) ) {
			opts.dtype = options.dtype;
		}
	}
	// Resolve the list of non-reduced dimensions:
	sh = getShape( x );
	if ( sh.length < 1 ) {
		throw new RangeError( 'invalid argument. First argument must have at least one dimension.' );
	}
	sh = nonCoreShape( sh, opts.dims );

	// Broadcast the `fromIndex` to match the shape of the non-reduced dimensions...
	if ( iflg ) {
		fidx = broadcastScalar( fidx, DEFAULT_DTYPE, sh, ord );
	} else {
		fidx = maybeBroadcastArray( fidx, sh );
	}
	return base( x, fidx, opts );
}


// EXPORTS //

export default indexOfFalsy;
